package com.coworkhub.controller;
import com.coworkhub.repository.*;import com.coworkhub.entity.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController public class AvailabilityController {private final RoomRepository rooms;private final BookingRepository bookings;public AvailabilityController(RoomRepository r,BookingRepository b){rooms=r;bookings=b;}
 @GetMapping("/api/disponibilidad")public List<Room> availability(@RequestParam Long sedeId,@RequestParam LocalDate fecha,@RequestParam LocalTime horaInicio,@RequestParam LocalTime horaFin,@RequestParam(required=false) Integer capacidadMinima,@RequestParam(required=false) List<Long> equipamientoIds){if(!horaInicio.isBefore(horaFin))throw new IllegalArgumentException("horaInicio debe ser anterior a horaFin");LocalDateTime start=fecha.atTime(horaInicio),end=fecha.atTime(horaFin);return rooms.findAllWithDetails().stream().filter(r->r.location.id.equals(sedeId)&&r.active&&horaInicio.compareTo(r.location.openingTime)>=0&&horaFin.compareTo(r.location.closingTime)<=0&&(capacidadMinima==null||r.capacity>=capacidadMinima)).filter(r->equipamientoIds==null||equipamientoIds.isEmpty()||r.equipment.stream().map(e->e.id).collect(java.util.stream.Collectors.toSet()).containsAll(equipamientoIds)).filter(r->bookings.findByRoomIdAndStatusInAndStartTimeLessThanAndEndTimeGreaterThan(r.id,List.of(Enums.BookingStatus.PENDING,Enums.BookingStatus.CONFIRMED),end,start).isEmpty()).toList();}}
